from datetime import datetime

FMT = "%d/%m/%Y %H:%M"

def durate(righe):
    out = {}
    for riga in righe:
        provino, inizio, fine = riga.split(";")
        d = datetime.strptime(fine, FMT) - datetime.strptime(inizio, FMT)
        if d.total_seconds() < 0:
            raise ValueError(f"{provino}: la fine è prima dell'inizio")
        out[provino] = int(d.total_seconds() // 60)
    return out

print(durate(["P01;14/03/2026 08:30;14/03/2026 09:10"]))
